export function searchFoods(query: string, limit = 30): FoodItem[] {
  const q = query.trim().toLowerCase();
  if (!q) return FOOD_DB.slice(0, limit);
  return FOOD_DB.filter((f) => {
    const haystack = `${f.name} ${f.keywords || ''} ${f.category}`.toLowerCase();
    return haystack.includes(q);
  }).slice(0, limit);
}

export function getFoodById(id: string): FoodItem | undefined {
  return FOOD_DB.find((f) => f.id === id);
}

export const FOOD_DB_SIZE = FOOD_DB.length;
